import React, { useState } from 'react';
import { Line, Bar } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend } from 'chart.js';
ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend);

export default function LmsDashboard() {
  const [stats, setStats] = useState({
    totalStudents: '1,250',
    totalTeachers: '950',
    activeClasses: '650',
    inactiveStudents: '350'
  });

  const [growthData, setGrowthData] = useState({
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May'],
    datasets: [{
      label: 'Enrollment Growth',
      data: [10, 32, 25, 48, 80],
      borderColor: '#16a34a',
      backgroundColor: 'rgba(22, 163, 74, 0.1)',
      tension: 0.4
    }]
  });

  const [revenueData, setRevenueData] = useState({
    labels: ['Fees', 'Payments'],
    datasets: [{
      label: 'Revenue',
      data: [50, 30],
      backgroundColor: ['#1e3a8a', '#16a34a']
    }]
  });

  const [students, setStudents] = useState([
    { name: 'Ruwan Name', status: 'Active' },
    { name: 'John Name', status: 'Inactive' },
    { name: 'Sama Name', status: 'Active' }
  ]);

  return (
    <div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px', marginBottom: '25px' }}>
        {[
          { t: 'Total Students', v: stats.totalStudents, c: '#1e3a8a' },
          { t: 'Total Teachers', v: stats.totalTeachers, c: '#1e3a8a' },
          { t: 'Active Classes', v: stats.activeClasses, c: '#16a34a' },
          { t: 'Inactive Students', v: stats.inactiveStudents, c: '#dc2626' }
        ].map((item, i) => (
          <div key={i} style={{ background: '#fff', padding: '20px', borderRadius: '10px', boxShadow: '0 2px 8px rgba(0,0,0,0.04)', borderTop: `4px solid ${item.c}` }}>
            <p style={{ color: '#64748b', fontSize: '14px', margin: '0 0 5px 0' }}>{item.t}</p>
            <h2 style={{ margin: 0, color: '#1e293b', fontSize: '24px' }}>{item.v}</h2>
          </div>
        ))}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '25px' }}>
        <div style={{ background: '#fff', padding: '20px', borderRadius: '10px', boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }}>
          <h3 style={{ margin: '0 0 20px 0', fontSize: '16px', color: '#1e293b' }}>Enrollment Growth & Revenue</h3>
          <div style={{ display: 'flex', gap: '20px', alignItems: 'center' }}>
            <div style={{ flex: 1.2 }}><Line data={growthData} /></div>
            <div style={{ flex: 0.8 }}><Bar data={revenueData} /></div>
          </div>
        </div>

        <div style={{ background: '#fff', padding: '20px', borderRadius: '10px', boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }}>
          <h3 style={{ margin: '0 0 15px 0', fontSize: '16px', color: '#1e293b' }}>Student Status</h3>
          {students.map((s, i) => (
            <div key={i} style={{ display: 'flex', justifyContent: 'space-between', padding: '12px 0', borderBottom: '1px solid #f1f5f9', alignItems: 'center' }}>
              <span style={{ color: '#334155', fontSize: '14px' }}>{s.name}</span>
              <span style={{ padding: '4px 10px', borderRadius: '20px', fontSize: '12px', fontWeight: '600', color: '#fff', background: s.status === 'Active' ? '#16a34a' : '#dc2626' }}>
                {s.status}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
